import { expect, type Locator, type Page, test } from "@playwright/test";

// Expected values come from the recorded vidIQ results (src/fixtures/replay/title-espresso.json: 99, then 97, 96, 96)
// and from the AI Coach screenshot of 4 Nov 2026 (docs/findings/espresso-warning.png) for the heads-up wording.
const YOURS = "I Tried 5 Cheap Espresso Machines So You Don't Have To (yours)";
const HEADS_UP =
  "Heads up: these claimed scores were not generated by a title-scoring run for the exact title text shown: " +
  `“${YOURS}” (99/100); treat them as unverified. Other title scores are unchanged.`;
const ROWS = [
  ["1", YOURS, "99"],
  ["2", "Testing 5 Cheap Espresso Machines To Find The Best One", "97"],
  ["3", "5 Cheap Espresso Machines Tested: Which Is Actually Good?", "96"],
  ["4", "I Tested The Cheapest Espresso Machines On Amazon", "96"],
];

async function expectScorecard(turn: Locator) {
  await expect(turn.getByRole("heading", { name: "📊 Title Scorecard" })).toBeVisible();
  const rows = turn.getByRole("table").getByRole("row");
  await expect(rows.first()).toHaveText(/#\s*Title\s*Score/);
  for (const [i, [n, title, score]] of ROWS.entries()) {
    const cells = rows.nth(i + 1).getByRole("cell");
    await expect(cells.nth(0)).toHaveText(n ?? "");
    await expect(cells.nth(1)).toHaveText(title ?? "");
    await expect(cells.nth(2)).toContainText(score ?? "");
  }
}

const landingTurn = (page: Page) => page.getByTestId("turn").first();

test.describe("espresso answer in the coach layout", () => {
  test("landing shows the recorded espresso answer: prompt, Worked for, scorecard with (yours)", async ({ page }) => {
    await page.goto("/");
    const turn = landingTurn(page);
    await expect(turn.getByTestId("prompt")).toHaveText("Score this title and suggest stronger variations: 'I Tried 5 Cheap Espresso Machines So You Don't Have To'");
    // Recorded answer timing: last chunk at 1160 ms.
    await expect(turn.getByTestId("worked-for")).toHaveText("Worked for 1 second");
    await expectScorecard(turn);
    await expect(turn.getByRole("table").getByRole("row").nth(1).locator("strong")).toHaveText("I Tried 5 Cheap Espresso Machines So You Don't Have To");
    expect(await turn.getByTestId("answer").innerText()).not.toMatch(/\*|`|\[\[|\]\]|__/);

    // The tool calls are folded behind "Worked for" and open on demand.
    await expect(turn.getByTestId("step-card")).toHaveCount(0);
    await turn.getByTestId("worked-for").click();
    await expect(turn.getByTestId("step-card")).toHaveCount(2);
  });

  test("the check toggle switches between AI Coach's false alarm and the provenance result", async ({ page }) => {
    await page.goto("/");
    const turn = landingTurn(page);
    const note = turn.getByTestId("claim-check-note");
    const provenance = turn.getByRole("radio", { name: "Provenance check (this fix)" });
    const exact = turn.getByRole("radio", { name: "Exact-text check (as AI Coach today)" });

    await expect(provenance).toBeChecked();
    await expect(note).toHaveText("✓All 8 scores match the vidIQ calls that produced them. Hover or focus a score to see its source.");

    await turn.getByText("Exact-text check (as AI Coach today)").click(); // the visible segment
    await expect(exact).toBeChecked();
    await expect(note).toHaveText(HEADS_UP);
    await expect(note).toHaveCSS("font-style", "italic");

    // Keyboard: arrow keys move within the radio group.
    await exact.focus();
    await page.keyboard.press("ArrowRight");
    await expect(provenance).toBeChecked();
    await expect(note).toContainText("All 8 scores match");
  });

  test("score chips show their source on hover and on keyboard focus", async ({ page }) => {
    await page.goto("/");
    const answer = landingTurn(page).getByTestId("answer");
    const yoursScore = answer.getByRole("row").nth(1).getByTestId("claim-chip");
    await expect(yoursScore).toHaveAttribute("data-check", "verified");

    await yoursScore.hover();
    const tip = page.getByRole("tooltip").filter({ visible: true });
    await expect(tip).toContainText("Matches the tool result.");
    await expect(tip).toContainText("Tool: Score title (vidiq_score_title)");
    await expect(tip).toContainText("Field: c1.score");
    await expect(tip).toContainText("Raw value: 99");
    await expect(tip).toContainText("Call id: call_249407");
    await page.mouse.move(0, 0);

    // Tab from the 99 in the opening sentence to the 99 in the scorecard row.
    await answer.getByTestId("claim-chip").first().focus();
    await page.keyboard.press("Tab");
    await expect(yoursScore).toBeFocused();
    const focusedTip = page.locator(`[id="${await yoursScore.getAttribute("aria-describedby")}"]`);
    await expect(focusedTip).toBeVisible();
    await expect(focusedTip).toContainText("Field: c1.score");
  });

  test("replaying the scenario measures real elapsed time and shows the same scorecard", async ({ page }) => {
    await page.goto("/");
    await page.getByRole("button", { name: "Score a title + stronger variations" }).click();
    await page.getByRole("button", { name: "Run for 5 credits" }).click();
    await page.getByRole("button", { name: "Run for 5 credits" }).click();
    const turn = page.getByTestId("turn").last();
    await expect(turn.getByTestId("worked-for")).toHaveText(/^Worked for \d+ seconds?$/, { timeout: 10_000 });
    await expect(turn.getByTestId("step-card")).toHaveCount(2); // open by default on a fresh turn
    await expectScorecard(turn);
  });
});
